import type { CustomExercise, Program } from '@/features/program';

// Exercise library (LIB-1..3): the free-exercise-db subset generated by
// scripts/build-exercises.ts into public/data/exercises.json (served as a
// static asset, precached), plus the program's custom exercises. Loaded once at
// app start via loadLibrary(); accessors are synchronous after that.

export interface Exercise {
  id: string;
  name: string;
  equipment: string;
  primaryMuscles: string[];
  secondaryMuscles: string[];
  instructions: string[];
  images: string[];
  category?: string;
  mechanic?: string | null;
  /** Images are bundled locally (program exercise) vs remote (swap pool only). */
  local: boolean;
  custom?: boolean;
}

let ALL: Exercise[] = [];
let byId = new Map<string, Exercise>();
let loading: Promise<void> | null = null;

/** Fetch the library once (idempotent). Safe to call from several places. */
export function loadLibrary(): Promise<void> {
  if (!loading) {
    loading = fetch('/data/exercises.json')
      .then((r) => (r.ok ? (r.json() as Promise<Exercise[]>) : []))
      .then((list) => {
        ALL = list;
        byId = new Map(list.map((e) => [e.id, e]));
      })
      .catch(() => {
        loading = null; // allow a retry later
      });
  }
  return loading;
}

export function isLibraryLoaded(): boolean {
  return ALL.length > 0;
}

export function getLibraryExercise(id: string): Exercise | null {
  return byId.get(id) ?? null;
}

export function fromCustom(c: CustomExercise): Exercise {
  return {
    id: c.id,
    name: c.name,
    equipment: c.equipment ?? 'body only',
    primaryMuscles: c.primaryMuscles ?? [],
    secondaryMuscles: c.secondaryMuscles ?? [],
    instructions: c.instructions ?? [],
    images: c.images ?? [],
    local: false,
    custom: true,
  };
}

/** Resolve an exercise by id: program custom exercises first, then the library. */
export function resolveExercise(program: Program | null, id: string): Exercise | null {
  const custom = program?.exercises?.find((e) => e.id === id);
  if (custom) return fromCustom(custom);
  return getLibraryExercise(id);
}

export function allEquipment(): string[] {
  return [...new Set(ALL.map((e) => e.equipment))].sort();
}

export function allMuscles(): string[] {
  return [...new Set(ALL.flatMap((e) => e.primaryMuscles))].sort();
}

export interface SearchFilters {
  muscle?: string;
  equipment?: string;
}

/** Full-library search for the add-exercise picker (WRK-16). */
export function searchExercises(queryText: string, filters: SearchFilters = {}): Exercise[] {
  const q = queryText.trim().toLowerCase();
  return ALL.filter((e) => {
    if (q && !e.name.toLowerCase().includes(q)) return false;
    if (filters.muscle && !e.primaryMuscles.includes(filters.muscle)) return false;
    if (filters.equipment && e.equipment !== filters.equipment) return false;
    return true;
  }).slice(0, 60);
}

/**
 * Swap suggestions (WRK-15): same primary muscle(s), filtered by the user's
 * available equipment (empty list = no filter; "body only" always allowed),
 * sorted by number of matching secondary muscles.
 */
export function similarExercises(
  base: Exercise,
  availableEquipment: string[],
  exclude: Set<string> = new Set(),
): Exercise[] {
  const primary = new Set(base.primaryMuscles);
  const secondary = new Set(base.secondaryMuscles);
  const allowEquipment = (eq: string) =>
    availableEquipment.length === 0 || eq === 'body only' || availableEquipment.includes(eq);

  return ALL.filter(
    (e) =>
      e.id !== base.id &&
      !exclude.has(e.id) &&
      e.primaryMuscles.some((m) => primary.has(m)) &&
      allowEquipment(e.equipment),
  )
    .map((e) => ({ e, score: e.secondaryMuscles.filter((m) => secondary.has(m)).length }))
    .sort((a, b) => b.score - a.score || a.e.name.localeCompare(b.e.name))
    .slice(0, 30)
    .map((x) => x.e);
}

/** All bundled image URLs, for the "Download for offline" step. */
export function localImageUrls(): string[] {
  return ALL.filter((e) => e.local).flatMap((e) => e.images);
}
